{"explanation": "This is the classic geometric proof of the geometric series 1/2 + 1/4 + 1/8 + ⋯ = 1. Start with a unit square: fill half of it (1/2), then half of what remains (1/4), then half of that remainder (1/8), and so on. After n steps the filled area is 1 − 1/2ⁿ and the empty gap is exactly 1/2ⁿ, which shrinks toward 0 as n grows — so the pieces must fill the entire square, meaning the infinite sum equals 1. Use the slider to show n terms, or replay the filling animation and watch the gap spiral into the corner and vanish.", "manimCode": "// ---------- Title ----------
const title = new Text({ text: '1/2 + 1/4 + 1/8 + 1/16 + ... = 1', color: WHITE, fontSize: 30 });
title.moveTo([0, 3.35, 0]);
const subtitle = new Text({ text: 'Fill half of what is left, over and over', color: GRAY, fontSize: 20 });
subtitle.moveTo([0, 2.95, 0]);

// ---------- Unit square (5x5 on screen) ----------
const unitSq = new Rectangle({ width: 5, height: 5, color: WHITE });
unitSq.setStrokeWidth(3);
unitSq.moveTo([0, 0, 0]);

// ---------- Piece geometry in unit coordinates ----------
const bl = [-2.5, -2.5]; // bottom-left corner of the square on screen
const side = 5;

const pieces = [];     // [xmin, ymin, xmax, ymax] of each filled piece
const remainders = []; // remaining empty region after each step
let rx = 0, ry = 0, rw = 1, rh = 1;
let cutHorizontal = true;
for (let i = 0; i < 8; i++) {
  if (cutHorizontal) {
    const h = rh / 2;
    pieces.push([rx, ry, rx + rw, ry + h]);
    ry += h; rh -= h;
  } else {
    const w = rw / 2;
    pieces.push([rx, ry, rx + w, ry + rh]);
    rx += w; rw -= w;
  }
  cutHorizontal = !cutHorizontal;
  remainders.push([rx, ry, rx + rw, ry + rh]);
}

const pieceColors = [BLUE_D, TEAL_D, GREEN_D, GOLD, ORANGE, RED_D, PURPLE, MAROON];
const labelStrs = ['1/2', '1/4', '1/8', '1/16', '1/32'];
const labelSizes = [36, 32, 28, 24, 20];

function pieceCenter(i) {
  const p = pieces[i];
  return [bl[0] + (p[0] + p[2]) / 2 * side, bl[1] + (p[1] + p[3]) / 2 * side, 0];
}

function makePieceRect(i) {
  const p = pieces[i];
  const w = (p[2] - p[0]) * side;
  const h = (p[3] - p[1]) * side;
  const r = new Rectangle({ width: w, height: h, color: WHITE });
  r.setStrokeWidth(1.5);
  r.setFill(pieceColors[i % pieceColors.length], 0.85);
  r.moveTo(pieceCenter(i));
  return r;
}

function makePieceLabel(i) {
  const t = new Text({ text: labelStrs[i], color: WHITE, fontSize: labelSizes[i] });
  t.moveTo(pieceCenter(i));
  return t;
}

// ---------- Mutable scene state ----------
let fillRects = [];
let fillLabels = [];
let sumLabel = null;
let gapLabel = null;
let limitDot = null;
let currentN = 0;
let animating = false;

function clearFills() {
  for (const r of fillRects) scene.remove(r);
  for (const l of fillLabels) scene.remove(l);
  fillRects = [];
  fillLabels = [];
}

function updateSumLabel(n) {
  if (sumLabel) scene.remove(sumLabel);
  let str;
  if (n === 0) {
    str = 'Sum = 0';
  } else {
    const d = Math.pow(2, n);
    str = 'Sum = 1 - 1/' + d + ' = ' + (d - 1) + '/' + d;
  }
  sumLabel = new Text({ text: str, color: WHITE, fontSize: 26 });
  sumLabel.moveTo([0, -3.2, 0]);
  scene.add(sumLabel);
}

function setFinalSumLabel() {
  if (sumLabel) scene.remove(sumLabel);
  sumLabel = new Text({ text: '1/2^n -> 0, so the infinite sum = 1', color: GOLD, fontSize: 24 });
  sumLabel.moveTo([0, -3.2, 0]);
  scene.add(sumLabel);
}

function updateGapLabel(n) {
  if (gapLabel) { scene.remove(gapLabel); gapLabel = null; }
  if (n >= 1 && n <= 5) {
    const g = remainders[n - 1];
    gapLabel = new Text({ text: 'gap = 1/' + Math.pow(2, n), color: YELLOW, fontSize: 16 });
    gapLabel.moveTo([bl[0] + (g[0] + g[2]) / 2 * side, bl[1] + (g[1] + g[3]) / 2 * side, 0]);
    scene.add(gapLabel);
  }
}

function updateLimitDot(n) {
  if (limitDot) { scene.remove(limitDot); limitDot = null; }
  if (n >= 6) {
    limitDot = new Dot({ point: [2.5, 2.5, 0], color: YELLOW });
    scene.add(limitDot);
  }
}

function showFills(n) {
  clearFills();
  for (let i = 0; i < n; i++) {
    const r = makePieceRect(i);
    scene.add(r);
    fillRects.push(r);
    if (i < labelStrs.length) {
      const l = makePieceLabel(i);
      scene.add(l);
      fillLabels.push(l);
    }
  }
  currentN = n;
  updateSumLabel(n);
  updateGapLabel(n);
  updateLimitDot(n);
}

async function animateFill(maxSteps) {
  if (animating) return;
  animating = true;
  clearFills();
  updateSumLabel(0);
  updateGapLabel(0);
  updateLimitDot(0);
  for (let i = 0; i < maxSteps; i++) {
    const r = makePieceRect(i);
    scene.add(r);
    fillRects.push(r);
    await scene.play(new FadeIn(r, { duration: 0.5 }));
    if (i < labelStrs.length) {
      const l = makePieceLabel(i);
      scene.add(l);
      fillLabels.push(l);
      await scene.play(new FadeIn(l, { duration: 0.3 }));
    }
    currentN = i + 1;
    updateSumLabel(currentN);
    updateGapLabel(currentN);
    updateLimitDot(currentN);
  }
  setFinalSumLabel();
  animating = false;
}

// ---------- Intro ----------
await scene.play(new Write(title));
await scene.play(new FadeIn(subtitle));
await scene.play(new Create(unitSq));

// ---------- Interactive controls ----------
const controls = new Controls(scene, { position: 'top-right', width: 250 });
controls.addSlider({
  label: 'Terms shown (n)',
  min: 0,
  max: 8,
  value: 8,
  step: 1,
  onChange: (v) => { if (!animating) showFills(Math.round(v)); }
});
controls.addButton({
  label: 'Replay animation',
  onClick: () => { animateFill(8); }
});

// ---------- Auto-play the filling once ----------
await animateFill(8);

await scene.wait(999999);"}

